/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input logic clk,
    input logic reset,
    input logic s,
    input logic w,
    output logic z
);
    typedef enum logic [2:0] {
        A, B_ZERO, B_MATCH, C_ZERO, C_ONE, D_ZERO, D_ONE, D_TWO
    } state_t;
    state_t state_r, state_n;

    always_comb begin
        state_n = A;
        case (state_r)
            A: begin
                if (s) state_n = B_ZERO;
                else state_n = A;
            end
            B_ZERO, B_MATCH: begin
                if (w) state_n = C_ONE;
                else state_n = C_ZERO;
            end
            C_ZERO: begin
                if (w) state_n = D_ONE;
                else state_n = D_ZERO;
            end
            C_ONE: begin
                if (w) state_n = D_TWO;
                else state_n = D_ONE;
            end
            D_ZERO: state_n = B_ZERO;
            D_ONE: begin
                if (w) state_n = B_MATCH;
                else state_n = B_ZERO;
            end
            D_TWO: begin
                if (w) state_n = B_ZERO;
                else state_n = B_MATCH;
            end
            default: state_n = A;
        endcase
    end

    always_ff @(posedge clk) begin
        if (reset) state_r <= A;
        else state_r <= state_n;
    end

    assign z = (state_r == B_MATCH);
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic reset = 0;
    logic s = 0;
    logic w = 0;
    wire z;
    TopModule dut (.clk(clk), .reset(reset), .s(s), .w(w), .z(z));
    always #5 clk = ~clk;

    bit active = 0;
    integer samples = 0;
    integer ones = 0;
    logic expected = 0;
    integer checks = 0;
    integer pattern;
    integer k;
    integer random_index;
    reg [31:0] rng = 32'"'h137abcde;

    // Independent oracle: count input samples in successive blocks of three.
    task automatic tick(input bit rst, input bit start, input bit value);
        logic before_z;
        begin
            @(negedge clk);
            before_z = z;
            reset = rst;
            s = start;
            w = value;
            #1;
            if (z "'!== before_z)
                $fatal(1, "Output changed away from clock edge");
            @(posedge clk);
            if (rst) begin
                active = 0;
                samples = 0;
                ones = 0;
                expected = 0;
            end else if (!active) begin
                expected = 0;
                if (start) active = 1;
            end else begin
                expected = 0;
                samples = samples + 1;
                if (value) ones = ones + 1;
                if (samples == 3) begin
                    expected = (ones == 2);
                    samples = 0;
                    ones = 0;
                end
            end
            #1;
            if (z !== expected)
                $fatal(1, "Check %0d: z=%b expected=%b samples=%0d ones=%0d", checks, z, expected, samples, ones);
            checks = checks + 1;
        end
    endtask

    initial begin
        tick(1, 1, 1);
        repeat (5) tick(0, 0, 1);
        // Every pair of three-bit groups, including consecutive matches.
        for (pattern = 0; pattern < 64; pattern = pattern + 1) begin
            tick(1, 0, 0);
            tick(0, 0, 1);
            tick(0, 1, 1); // w on entry into B must not be sampled.
            for (k = 0; k < 6; k = k + 1)
                tick(0, k[0], ((pattern >> k) & 1));
            tick(0, 0, 0);
        end
        // Reset at each sampling phase and during an asserted result.
        for (k = 0; k < 4; k = k + 1) begin
            tick(1, 1, 1);
            tick(0, 1, 0);
            if (k >= 1) tick(0, 0, 1);
            if (k >= 2) tick(0, 0, 1);
            if (k >= 3) tick(0, 0, 0);
            tick(1, 1, 1);
            tick(0, 0, 1);
        end
        for (random_index = 0; random_index < 600; random_index = random_index + 1) begin
            rng = {rng[30:0], rng[31] ''^ rng[21] ''^ rng[1] ''^ rng[0]};
            tick(rng[7:3] == 0, rng[1], rng[0]);
        end
        $display("PASS %0d cycle checks", checks);
        $finish;
    end
    initial begin
        #20000;
        $fatal(1, "Timeout");
    end
endmodule
EOF
python3 dev_check.py --label initial'

